import {test,expect} from '@playwright/test';
import {start,settled,seed,checkpoint,enterBoss} from './helpers.js';
test('real rig, dimensional gemstone, responsive conversations and optional research charts',async({page})=>{
 const errors=[];page.on('pageerror',e=>errors.push(e.message));await seed(page,checkpoint({exile:true,ended:true}));await start(page,true);
 const asset=await page.evaluate(()=>{const w=window.__profileWorld,g=w.gems[0];g.geometry.computeBoundingBox();let skins=0,vertices=0;w.npc.traverse(o=>{if(o.isSkinnedMesh){skins++;vertices+=o.geometry.attributes.position.count;}});return{skins,vertices,height:g.geometry.boundingBox.max.y-g.geometry.boundingBox.min.y,width:g.geometry.boundingBox.max.x-g.geometry.boundingBox.min.x,facets:g.geometry.attributes.position.count,mode:w.getQuality(),transmission:g.material.transmission};});
 expect(asset.skins).toBeGreaterThanOrEqual(5);expect(asset.vertices).toBeGreaterThan(10000);expect(asset.height).toBeGreaterThan(.7);expect(asset.width).toBeGreaterThan(.8);expect(asset.facets).toBeGreaterThan(100);expect(asset.mode).toBe('performance');expect(asset.transmission).toBe(0);
 await page.locator('#quality').click();expect(await page.evaluate(()=>window.__profileWorld.gems[0].material.transmission)).toBeGreaterThan(0);await page.locator('#quality').click();
 await page.getByRole('button',{name:'Descend to the scholars',exact:true}).click();await page.getByRole('button',{name:'Approach The Stonekeeper',exact:true}).click();await expect(page.locator('#portrait')).toHaveJSProperty('naturalWidth',768);
 for(const viewport of [{width:1366,height:768},{width:1920,height:1080}]){await page.setViewportSize(viewport);const bounds=await page.locator('#panel').boundingBox();expect(bounds.y).toBeGreaterThan(60);expect(bounds.y+bounds.height).toBeLessThan(viewport.height-45);const portrait=await page.locator('#portrait').boundingBox(),copy=await page.locator('#panel-copy').boundingBox();expect(copy.x).toBeGreaterThanOrEqual(portrait.x+portrait.width);await page.screenshot({path:`qa/complete-dialogue-${viewport.width}.png`});}
 await page.locator('#close-panel').click();await settled(page);await page.locator('#codex-button').click();
 const chapters={Form:['Carat distribution','Depth distribution'],Division:['Projected K-Means groups','Median weights and prices'],Memory:['Variance retained','K-Means before PCA','K-Means after PCA','Silhouette comparison'],Exile:['DBSCAN before PCA','DBSCAN after PCA']};
 for(const [tab,plots] of Object.entries(chapters)){await page.getByRole('button',{name:tab,exact:true}).click();for(const label of plots){await page.getByRole('button',{name:label,exact:true}).click();await expect(page.locator('#research-chart .main-svg').first()).toBeVisible();await expect(page.getByRole('button',{name:label,exact:true})).toHaveAttribute('aria-pressed','true');}}
 await page.getByRole('button',{name:'The Truth',exact:true}).click();await expect(page.locator('#codex-body')).toContainText('88.12%');await page.keyboard.press('Escape');await expect(page.locator('#codex')).not.toBeVisible();expect(await page.evaluate(()=>window.__game.scene())).toBe('crypt');expect(errors).toEqual([]);
});
test('active character idle moves naturally; reduced motion freezes its rig',async({page})=>{
 await seed(page,checkpoint({location:'crypt'}));await start(page,true);await page.locator('#motion').click();
 const bones=()=>page.evaluate(()=>{let head;window.__profileWorld.npc.traverse(o=>{if(o.isBone&&o.name==='head')head=o;});return head.matrixWorld.elements;});
 const first=await bones();await page.waitForTimeout(1000);expect(await bones()).not.toEqual(first);await page.locator('#motion').click();await page.waitForTimeout(100);const frozen=await bones();await page.waitForTimeout(300);expect(await bones()).toEqual(frozen);
});
test('battle and Archive remain within a laptop viewport',async({page})=>{
 await seed(page,checkpoint({exile:true}));await page.setViewportSize({width:1366,height:768});await start(page,true);await page.locator('#journey-button').click();await page.getByRole('button',{name:'Presenter Mode',exact:true}).click();await page.getByRole('button',{name:'Face The Veiled Mirror',exact:true}).click();await page.getByRole('button',{name:'Begin the encounter',exact:true}).click();await page.screenshot({path:'qa/complete-battle-1366.png'});const panel=await page.locator('#panel').boundingBox();expect(panel.y).toBeGreaterThan(60);expect(panel.y+panel.height).toBeLessThan(720);await page.locator('#presenter-controls').click();await page.getByRole('button',{name:'Replay the final revelation',exact:true}).click();await expect(page.locator('#panel-title')).toHaveText('The stones were never lost');await page.screenshot({path:'qa/complete-archive-1366.png'});expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBe(1366);
});
